<script setup lang="ts">
import {computed,ref} from 'vue'
const items=[{id:'overview',label:'Overview',count:3,description:'Sample project summary',disabled:false},{id:'activity',label:'Activity',count:12,description:'Fictitious recent events',disabled:false},{id:'archive',label:'Archive',count:0,description:'Unavailable in this demo',disabled:true}]
const selected=ref('overview'),query=ref(''),variant=ref('bordered')
const filtered=computed(()=>items.filter(i=>i.label.toLowerCase().includes(query.value.toLowerCase())))
const active=computed(()=>items.find(i=>i.id===selected.value)!)
function reset(){selected.value='overview';query.value='';variant.value='bordered'}
</script>
<template><section class="list-group-usage" aria-label="List group usage demonstration"><p>Fictitious local list. No navigation or request occurs when selecting an item.</p><div class="options"><label>List appearance<select v-model="variant"><option>bordered</option><option>flush</option><option>horizontal</option></select></label><label>Filter sample items<input v-model="query" type="search"></label><button type="button" @click="reset">Reset list</button></div><ul class="items" :class="variant" aria-label="Sample sections"><li v-for="item in filtered" :key="item.id"><button type="button" :disabled="item.disabled" :aria-pressed="selected===item.id" @click="selected=item.id"><span><strong>{{item.label}}</strong><small>{{item.description}}</small></span><span class="badge" :aria-label="`${item.count} sample items`">{{item.count}}</span></button></li></ul><p v-if="!filtered.length" role="status">No sample items match. Clear the filter to restore the list.</p><p v-else role="status">Selected: {{active.label}}. Counts are fictitious.</p><article><h3>{{active.label}} sample detail</h3><p>{{active.description}}. Filtering does not reset the selected record.</p></article><nav aria-label="Guide section links"><p>Linked list pattern: these are actual links, not selection buttons.</p><ul><li><a href="#list-group-anatomy">Read anatomy</a></li><li><a href="#list-group-sources">Read source coverage</a></li></ul></nav></section></template>
<style scoped>
.list-group-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}.options{display:flex;gap:14px;flex-wrap:wrap;align-items:end}label{display:flex;flex-direction:column;gap:8px;max-width:100%}button,select,input{min-height:44px;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}input{width:220px;max-width:100%}.items{list-style:none!important;padding:0!important;border:1px solid var(--vp-c-divider);border-radius:9px;overflow:hidden;margin:22px 0}.items li{margin:0!important}.items button{width:100%;display:flex;justify-content:space-between;gap:12px;text-align:left;border:0;border-bottom:1px solid var(--vp-c-divider);border-radius:0;transition:background 150ms ease-out}.items li:last-child button{border-bottom:0}.items button[aria-pressed=true]{box-shadow:inset 4px 0 var(--vp-c-brand-1);background:var(--vp-c-brand-soft)}.items small{display:block;color:var(--vp-c-text-2);margin-top:4px}.badge{align-self:center;border:1px solid var(--vp-c-divider);border-radius:20px;padding:2px 9px;white-space:nowrap}.items button:disabled{opacity:.55;cursor:not-allowed}.items.flush{border-left:0;border-right:0;border-radius:0}.items.horizontal{display:flex}.horizontal li{flex:1;min-width:0}.horizontal button{height:100%;border-right:1px solid var(--vp-c-divider);border-bottom:0;flex-wrap:wrap}.horizontal li:last-child button{border-right:0}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:-3px}@media(max-width:700px){.items.horizontal{display:block}.horizontal button{border-right:0;border-bottom:1px solid var(--vp-c-divider)}}@media(prefers-reduced-motion:reduce){.items button{transition:none}}
</style>
